        getChartData(state) {
            const ds = state.domainState || {};
            const runwayHistory = ds.runwayHistory || [];
            const equityHistory = ds.equityHistory || [];
            const labels = runwayHistory.map((_, i) => this._t('round_label', 'R') + ' ' + (i + 1));
            return {
                runwayChart: {
                    labels: labels,
                    datasets: [{ data: runwayHistory }]
                },
                equityChart: {
                    labels: labels,
                    datasets: [{ data: equityHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};

            const last = history[history.length - 1];
            const final = last.results || {};
            const ds = last.domainState || {};

            const finalScore = (final.finalScore != null) ? final.finalScore
                : (ds.score != null ? ds.score : 0);

            let band;
            let insights = [];

            if (finalScore > 80) {
                band = this._t('band_fundable', 'Fundable');
                insights.push(this._t('insight_strong', 'Strong founder-friendly outcome with balanced growth and control.'));
            } else if (finalScore > 60) {
                band = this._t('band_promising', 'Promising');
                insights.push(this._t('insight_solid', 'Solid fundamentals with specific areas for optimization.'));
            } else if (finalScore > 40) {
                band = this._t('band_struggling', 'Struggling');
                insights.push(this._t('insight_survived', 'Survived but significant errors in capital allocation.'));
            } else {
                band = this._t('band_needs_work', 'Needs Work');
                insights.push(this._t('insight_critical', 'Critical errors in pivot timing, fundraising, or team building.'));
            }

            if (ds.insolvent) insights.push(this._t('insight_insolvent', 'Insolvent at exit — the company ran out of cash. Score capped at 40.'));
            if (ds.pivotMade && ds.pmfScore < 50) insights.push(this._t('insight_pivot_weak', 'Pivot executed but PMF still weak — consider earlier validation.'));
            if (ds.founderEquity < 40) insights.push(this._t('insight_dilution', 'Excessive dilution — control compromised for future rounds.'));
            if (ds.runway < 6) insights.push(this._t('insight_runway', 'Runway crisis — fundraising under pressure destroys leverage.'));
            if (ds.raiseUnderfunded) insights.push(this._t('insight_underfunded', 'Series A underfunded — investors did not fully subscribe at your ask.'));
            if (ds.nps > 50 && ds.mrr < 10000) insights.push(this._t('insight_monetization', 'Happy users but monetization too conservative.'));

            return {
                finalScore,
                overallScore: finalScore,
                band,
                grade: this._grade(finalScore),
                founderEquity: (ds.founderEquity != null ? ds.founderEquity.toFixed(1) : '0.0') + '%',
                runway: ds.runway,
                mrr: '$' + ((ds.mrr || 0) / 1000).toFixed(1) + 'K',
                teamSize: ds.teamSize,
                pmfScore: ds.pmfScore,
                insights
            };
        }

        /**
         * NOTE: the framework calls getHint() AFTER advancing currentPeriod,
         * so the period that was just played is results.period — using
         * state.currentPeriod here (v1.0.0) evaluated the wrong round's rules.
         */
        getHint(state, results) {
            const ds = state.domainState || {};
            const d = state.decisions || {};
            const q = (results && results.period) ? results.period : (state.currentPeriod || 1);

            if (ds.insolvent) return this._t('hint_insolvent', 'You are out of cash. Burn discipline is now the only lever left.');
            if (q === 1 && d.discoveryBudget < 10000) return this._t('hint_discovery_low', 'Low discovery budget increases risk of building the wrong thing.');
            if (q === 1 && (d.mvpFeatures || []).length > 3) return this._t('hint_mvp_scope', 'Too many features delay launch. Consider Jobs-to-be-Done focus.');
            if (q === 2 && ds.pmfScore < 35 && d.pivotDecision === 'persevere') return this._t('hint_consider_pivot', 'Low PMF signals suggest pivot may be warranted.');
            if (q === 2 && ds.runway < 12 && d.bridgeDecision === 'none') return this._t('hint_bridge_consider', 'Runway below 12 months. Bridge financing may be prudent.');
            if (q === 3 && ds.raiseUnderfunded) return this._t('hint_underfunded', 'The round did not fully subscribe — your ask outran your traction.');
            if (q === 3 && d.valuationAsk > 8 && ds.mrr < 20000) return this._t('hint_valuation_high', 'High valuation ask with current MRR may reduce close probability.');
            if (q === 3 && d.termSheet === 'growth' && ds.founderEquity < 60) return this._t('hint_terms_dilutive', 'Growth terms with existing dilution may compromise long-term control.');
            return null;
        }

